require_once __DIR__.'/noticias_comun.php'; $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); $admin=(int)($_SESSION['es_admin']??0)===1; $st=db()->prepare("SELECT * FROM noticias WHERE id=? AND (estado='publicada' OR ?=1)");$st->execute([$id?:0,$admin?1:0]);$n=$st->fetch();if(!$n)http_response_code(404); $plantilla=$n['plantilla']??'clasica'; $plantillasValidas=['clasica','ultima_hora','analisis','cronologia','galeria','entrevista','marcador'];if(!in_array($plantilla,$plantillasValidas,true))$plantilla='clasica'; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($n['seo_titulo']?:($n['titulo']??'Artículo no encontrado'))?> | Papoyisa</title><meta name="description" content="<?=h($n['seo_descripcion']?:($n['resumen']??''))?>"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="noticias.css"><?=papoyisa_estilo()?> <style>.articulo-antetitulo{color:#b77a00;font-weight:800;letter-spacing:.12em}.articulo-subtitulo{font-size:1.25rem;color:#555}.articulo-portada-img{width:100%;max-height:520px;object-fit:cover;border-radius:16px}.pie-foto{font-size:.9rem;color:#666;margin-top:6px}.articulo-contenido{white-space:pre-wrap;line-height:1.85;font-size:1.08rem}.articulo-tags{margin-top:24px;color:#555}.etiqueta-plantilla{display:inline-block;margin:12px 0;padding:7px 12px;border-radius:5px;background:#174c83;color:#fff;font-size:.75rem;font-weight:900;letter-spacing:.12em}.plantilla-ultima_hora .etiqueta-plantilla{background:#c62828}.plantilla-ultima_hora .articulo-texto{border-top:6px solid #c62828;padding-top:18px}.plantilla-analisis .articulo-texto{max-width:780px;margin:auto;font-family:Georgia,serif}.plantilla-analisis .articulo-resumen{border-left:5px solid #d6a900;padding:16px 22px;background:#fff8dc;font-size:1.2rem}.plantilla-cronologia .articulo-contenido h2{border-left:4px solid #174c83;padding:10px 14px;background:#eef5fb}.plantilla-galeria .articulo-portada-img{max-height:650px;object-fit:contain;background:#111}.plantilla-galeria .articulo-contenido figure{margin:30px 0}.plantilla-galeria .articulo-contenido figure img{width:100%;height:auto;border-radius:12px}.plantilla-entrevista .articulo-contenido p strong:first-child{color:#174c83}.plantilla-marcador .articulo-resumen{padding:22px;border-radius:14px;background:#edf4fa;font-weight:700;text-align:center;font-size:1.25rem}.articulo-contenido figure img{max-width:100%;height:auto}.articulo-contenido blockquote{margin:24px 0;padding:18px 24px;border-left:5px solid #e0b400;background:#fff9df;font-size:1.2rem;font-weight:600}.articulo-contenido a{color:#145b9a;text-decoration:underline}.fuentes-lista{padding-left:22px;line-height:1.8}.btn-regresar{display:inline-block;margin:24px 0;padding:10px 16px;border-radius:8px;background:#174c83;color:#fff;text-decoration:none;font-weight:700}</style></head><body><header class="top"><a class="logo" href="index.php">🍌 Papoyisa</a><a href="index.php">Inicio</a></header><main class="pagina-noticias pagina-articulo plantilla-<?=h($plantilla)?>"><?php if(!$n):?><h1>Artículo no encontrado</h1><?php else:?><article class="articulo-completo"><?php if($n['imagen']):?><img class="articulo-portada-img" src="<?=h($n['imagen'])?>" alt="<?=h($n['imagen_alt']??'')?>"><?php if($n['pie_imagen']):?><p class="pie-foto"><?=h($n['pie_imagen'])?></p><?php endif;?><?php endif;?><div class="articulo-texto"><?php if($n['antetitulo']):?><div class="articulo-antetitulo"><?=h($n['antetitulo'])?></div><?php endif;?><div class="etiqueta-plantilla"><?=h(['clasica'=>'NOTICIA','ultima_hora'=>'ÚLTIMA HORA','analisis'=>'ANÁLISIS Y OPINIÓN','cronologia'=>'EN CRONOLOGÍA','galeria'=>'ESPECIAL FOTOGRÁFICO','entrevista'=>'ENTREVISTA','marcador'=>'RESULTADO DEPORTIVO'][$plantilla])?></div><div class="articulo-meta"><?=h(strtoupper($n['categoria']))?> · <?=h($n['subcategoria'])?> · <?=h($n['fecha_publicacion']?date('d/m/Y',strtotime($n['fecha_publicacion'])):'Borrador')?></div><h1><?=h($n['titulo'])?></h1><?php if($n['subtitulo']):?><p class="articulo-subtitulo"><?=h($n['subtitulo'])?></p><?php endif;?><p class="articulo-resumen"><?=h($n['resumen'])?></p><p>Por <b><?=h($n['autor']?:'Redacción Papoyisa')?></b></p><div class="articulo-contenido"><?php if(!empty($n['contenido_html'])):?><?=$n['contenido_html']?><?php else:?><?=nl2br(h($n['contenido']))?><?php endif;?></div><?php if($n['etiquetas']):?><p class="articulo-tags">Etiquetas: <?=h($n['etiquetas'])?></p><?php endif;?><?php if($n['fuente']):?><div class="articulo-fuente"><b>Fuentes consultadas:</b><ul class="fuentes-lista"><?php foreach(preg_split('/\R+/',trim((string)$n['fuente'])) as $fuenteUrl):$fuenteUrl=trim($fuenteUrl);if(filter_var($fuenteUrl,FILTER_VALIDATE_URL)&&strtolower((string)parse_url($fuenteUrl,PHP_URL_SCHEME))==='https'):?><li><a href="<?=h($fuenteUrl)?>" target="_blank" rel="noopener noreferrer"><?=h(parse_url($fuenteUrl,PHP_URL_HOST)?:$fuenteUrl)?></a></li><?php endif;endforeach;?></ul></div><?php endif;?></div></article><?php endif;?><a class="btn-regresar" id="btnRegresar" href="noticias.php">← Regresar</a><script>(function(){const b=document.getElementById("btnRegresar");b.addEventListener("click",function(e){if(document.referrer){try{const r=new URL(document.referrer);if(r.origin===location.origin){e.preventDefault();history.back();}}catch(_){}}});})();</script></main></body></html>